@push('scripts')<script>document.querySelectorAll(".builder-tab").forEach(b=>b.addEventListener("click",()=>{document.querySelectorAll(".builder-tab").forEach(x=>x.classList.toggle("active",x===b));document.querySelectorAll(".builder-panel").forEach(p=>p.classList.toggle("active",p.dataset.panel===b.dataset.tab));}));
(()=>{const list=document.getElementById('blocks-list'),hidden=document.getElementById('builder-blocks-json'),add=document.getElementById('add-block');if(!list||!hidden)return;
let blocks=[];try{const parsed=JSON.parse(hidden.value||'[]');blocks=Array.isArray(parsed)?parsed:[]}catch(e){blocks=[]}
const types={hero:'Hero',text:'Text',image:'Image',image_text:'Image + Text',gallery:'Gallery',video:'Video',cta:'CTA',button:'Button',html:'Custom HTML',divider:'Divider'};
const defaults={hero:{title:'',content:'',image:'',url:'',visible:true},text:{title:'',content:'',image:'',url:'',visible:true},image:{title:'',content:'',image:'',url:'',visible:true},image_text:{title:'',content:'',image:'',url:'',visible:true},gallery:{title:'',content:'',image:'',url:'',visible:true},video:{title:'',content:'',image:'',url:'',visible:true},cta:{title:'',content:'',image:'',url:'',visible:true},button:{title:'',content:'',image:'',url:'',visible:true},html:{title:'',content:'',image:'',url:'',visible:true},divider:{title:'',content:'',image:'',url:'',visible:true}};
function sync(){hidden.value=JSON.stringify(blocks);render();}
function safe(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));}
function render(){list.innerHTML='';blocks.forEach((b,i)=>{const row=document.createElement('div');row.className='block-row';row.draggable=true;row.dataset.i=i;row.innerHTML='<div class="block-head"><span class="grip">☷</span><select class="bt">'+Object.entries(types).map(([k,v])=>'<option value="'+k+'" '+(b.type===k?'selected':'')+'>'+v+'</option>').join('')+'</select><button type="button" class="block-remove">Remove</button></div><div class="block-fields"><input class="wide title" placeholder="Section title" value="'+safe(b.title)+'"><textarea class="wide body" rows="3" placeholder="Section content">'+safe(b.content)+'</textarea><input class="image" placeholder="Image URL (optional)" value="'+safe(b.image)+'"><input class="url" placeholder="Link / Button URL (optional)" value="'+safe(b.url)+'"><label class="check"><input class="visible" type="checkbox" '+(b.visible!==false?'checked':'')+'> Visible</label></div>';
row.querySelector('.bt').onchange=e=>{b.type=e.target.value;const d=defaults[b.type]||defaults.text;Object.keys(d).forEach(k=>{if(b[k]===undefined)b[k]=d[k]});sync()};row.querySelector('.title').oninput=e=>{b.title=e.target.value;hidden.value=JSON.stringify(blocks)};row.querySelector('.body').oninput=e=>{b.content=e.target.value;hidden.value=JSON.stringify(blocks)};row.querySelector('.image').oninput=e=>{b.image=e.target.value;hidden.value=JSON.stringify(blocks)};row.querySelector('.url').oninput=e=>{b.url=e.target.value;hidden.value=JSON.stringify(blocks)};row.querySelector('.visible').onchange=e=>{b.visible=e.target.checked;hidden.value=JSON.stringify(blocks)};row.querySelector('.block-remove').onclick=()=>{blocks.splice(i,1);sync()};row.ondragstart=()=>row.classList.add('dragging');row.ondragover=e=>e.preventDefault();row.ondrop=()=>{const from=+row.dataset.i;if(from===i)return;const x=blocks.splice(from,1)[0];blocks.splice(i,0,x);sync()};row.ondragend=()=>row.classList.remove('dragging');list.appendChild(row)})}
add.onclick=()=>{const type='text';blocks.push({...defaults[type],type});sync()};render();})();
</script>@endpush
